from typing import Dict, Any


def _safe_num(x: Any) -> float | None:
    try:
        if x is None:
            return None
        if isinstance(x, (int, float)):
            return float(x)
        return float(str(x).strip())
    except Exception:
        return None


def risk_score(data: Dict[str, Any]) -> float:
    """
    Compute a background screening support risk score in [0, 1].

    Heuristics focus on indicators of verification difficulty and data anomalies
    (e.g., ambiguous school names, identity collision risks, invalid formats),
    plus a light signal from credit score as a proxy for potential public-record
    findings. Avoids using sensitive or location-based proxies as risk factors.
    """
    score = 0.0

    # Keys we expect; missing/blank fields tend to slow verification.
    expected = ["name", "zipcode", "school_attended", "credit_score"]
    missing = 0
    for k in expected:
        v = data.get(k, None)
        if v is None or (isinstance(v, str) and not v.strip()):
            missing += 1
    if missing:
        score += min(0.15 * missing, 0.45)

    # Zip code format only (avoid geographic proxies).
    zipcode = str(data.get("zipcode", "")).strip()
    if not zipcode.isdigit() or len(zipcode) not in (5, 9):
        score += 0.2

    # Name-based record collision heuristics (format/complexity, not ethnicity).
    name = str(data.get("name", "")).strip()
    if name:
        parts = [p for p in name.replace(",", " ").split() if p]
        if any("-" in p or "'" in p for p in parts):
            score += 0.05
        if any(suf in name for suf in (" Jr", " Sr", " II", " III", " IV")):
            score += 0.07

        # Very common names can increase false matches.
        common_first = {
            "james","john","robert","michael","william","mary","patricia","jennifer","linda","elizabeth",
            "david","joseph","thomas","charles","christopher","daniel","matthew","anthony","mark","donald",
        }
        common_last = {
            "smith","johnson","williams","brown","jones","garcia","miller","davis","rodriguez","martinez",
            "hernandez","lopez","gonzalez","wilson","anderson","thomas","taylor","moore","jackson","martin",
        }
        first = parts[0].lower() if parts else ""
        last = parts[-1].lower() if parts else ""
        if first in common_first and last in common_last:
            score += 0.15
        elif first in common_first or last in common_last:
            score += 0.08

    # School verification difficulty (ambiguous/generic names or hard-to-verify modes).
    school = str(data.get("school_attended", "")).strip().lower()
    if school:
        generic_tokens = ["high school", "public high school", "academy", "district"]
        if any(tok in school for tok in generic_tokens):
            score += 0.12
        hard_verify_tokens = ["online", "virtual", "charter", "ged", "home school", "homeschool"]
        if any(tok in school for tok in hard_verify_tokens):
            score += 0.18

    # Credit score as a light signal for potential judgments/collections in record checks.
    cs = _safe_num(data.get("credit_score"))
    if cs is None:
        score += 0.1  # unknown credit adds slight uncertainty
    else:
        if cs < 580:
            score += 0.25
        elif cs < 650:
            score += 0.15
        elif cs < 700:
            score += 0.08

    # Clamp to [0, 1]
    return max(0.0, min(1.0, score))


if __name__ == "__main__":
    import json, sys
    path = "/workspace/background.json"
    try:
        with open(path, "r", encoding="utf-8") as f:
            sample = json.load(f)
        print(risk_score(sample))
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
